input.command:
awk 'BEGIN{
dh=1530*(566-288); printf "dh=%d J/kg; kg/kWh=%.4f\n",dh,3600000/dh;
mact=5000*3600000/dh; m=mact/0.85; printf "m_act=%.0f m=%.0f\n",mact,m;
rho=2090-0.636*566; V=1.1*m/rho; D=exp(log(4*V/3.141592653589793)/3); A=1.5*3.141592653589793*D*D; printf "rho=%.1f V=%.3f D=%.4f A=%.3f\n",rho,V,D,A;
st=A*0.008*7900*1.3; printf "steel=%.0f hot=%.0f cold=%.0f\n",st,st*18,st*7;
Aw=A*1.25/1.5; Af=A/6; ins=2*Aw*150; fdn=2*Af*1500; printf "Aw=%.3f Af=%.3f ins=%.0f fdn=%.0f\n",Aw,Af,ins,fdn;
salt=m*0.9; dir=salt+st*25+ins+fdn+80000+40000+50000; tot=dir*1.35; printf "salt=%.0f direct=%.0f total=%.0f perkWh=%.2f\n",salt,dir,tot,tot/5000;
q=0.25*A*(541+263)*1.5; eta=1-q*24/1000/5000; printf "q=%.0f eta=%.4f\n",q,eta;
s=tot/5000/(10950*eta); crf=0.07*1.07^30/(1.07^30-1); lev=tot*crf/(5000*eta*365); printf "simple=%.4f $/kWh crf=%.5f lev=%.4f $/kWh\n",s,crf,lev;
printf "floor kg/kWh=%.3f $/kWh=%.2f\n",3600000/(1530*306),0.5*3600000/(1530*306);
printf "hoop t=%.2f mm\n",1730*9.81*3.5*1.75/80e6*1000;
printf "fixed share=%.3f salt share=%.3f elec=%.1f\n",170000/dir,salt/dir,(tot/5000)/0.30}'
